### 12.5 ioctl 透传核心函数

```c
/* 通用 ioctl 透传 — Proxy 模式的核心 */
static int virtio_media_proxy_ioctl(struct virtio_media_session *s,
                                    uint32_t code,
                                    void *payload_in,
                                    size_t in_size,
                                    void *payload_out,
                                    size_t out_size)
{
  int ret;

  /* 对于 _IOWR 型：先把输入 payload 拷贝到输出（模拟同一块内存） */
  if (payload_in && payload_out && in_size > 0)
    memcpy(payload_out, payload_in, in_size);

  /* 直接调用本地 V4L2 ioctl */
  ret = ioctl(s->host_fd, code, payload_out ? payload_out : payload_in);
  if (ret < 0)
    return errno;    /* 返回正数 errno 给协议层 */

  return 0;
}
```

对于绝大多数 ioctl（`G_FMT`、`S_FMT`、`ENUM_FMT`、`G_PARM`、`S_PARM` 等），这一个函数就足够了。只有涉及 buffer 操作（QBUF/REQBUFS）和事件订阅的 ioctl 需要额外的状态追踪。

### 12.6 QBUF 的地址转换

Guest 提交的 USERPTR buffer 携带的是 Guest 物理地址，Host 不能直接使用。Proxy Backend 需要做地址转换：

```mermaid
flowchart TD
    A["Guest QBUF: v4l2_buffer + SG entries"] --> B["遍历每个 plane 的 SG entries"]
    B --> C["将 Guest 物理地址映射到 Host 虚拟地址"]
    C --> D["替换 buffer.m.userptr 为 Host 地址"]
    D --> E["ioctl(host_fd, VIDIOC_QBUF, &host_buffer)"]
    E --> F["记录 Host→Guest 地址映射关系"]
    F --> G["DQBUF 时恢复 Guest 原始地址后推送事件"]
```

```c
static int virtio_media_proxy_qbuf(struct virtio_media_session *s,
                                   struct v4l2_buffer *guest_buf,
                                   struct sg_entry *sg_list,
                                   int sg_count)
{
  struct v4l2_buffer host_buf = *guest_buf;
  void *host_addr;
  int ret;

  /* 将 Guest SG entries 映射到 Host 可访问的连续虚拟地址 */
  host_addr = map_guest_memory(sg_list, sg_count);
  if (!host_addr)
    return ENOMEM;

  /* 替换为 Host 侧地址 */
  host_buf.m.userptr = (unsigned long)host_addr;

  /* 记录映射关系，DQBUF 时需要恢复 */
  record_addr_mapping(s, host_addr, guest_buf->m.userptr);

  ret = ioctl(s->host_fd, VIDIOC_QBUF, &host_buf);
  if (ret < 0)
    {
      unmap_guest_memory(host_addr);
      return errno;
    }

  s->capture_queued++;
  return 0;
}
```

### 12.7 异步 DQBUF 事件推送

Host Backend 用 `epoll` 监听真实设备的 `CAPTURE` 就绪事件，然后通过 eventq 推送给 Guest：

```mermaid
flowchart TD
    A["epoll_wait(host_fd)"] --> B{"事件类型？"}
    B -->|"EPOLLIN (帧就绪)"| C["ioctl(host_fd, VIDIOC_DQBUF, &buf)"]
    B -->|"EPOLLPRI (V4L2事件)"| D["ioctl(host_fd, VIDIOC_DQEVENT, &evt)"]
    C --> E["恢复 Guest 原始地址"]
    E --> F["构造 EVT_DQBUF 事件"]
    F --> G["写入 eventq descriptor"]
    G --> H["通知 Guest"]
    D --> I["构造 EVT_EVENT 事件"]
    I --> G
```

```c
/* Backend 主循环中的事件处理 */
static void virtio_media_poll_host_device(struct virtio_media_backend *be,
                                          struct virtio_media_session *s)
{
  struct v4l2_buffer buf;
  int ret;

  memset(&buf, 0, sizeof(buf));
  buf.type = s->capture_queue_type;
  buf.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(s->host_fd, VIDIOC_DQBUF, &buf);
  if (ret < 0)
    return;  /* EAGAIN = 无帧就绪 */

  /* 恢复 Guest 原始地址 */
  buf.m.userptr = lookup_guest_addr(s, (void *)buf.m.userptr);
  s->capture_queued--;

  /* 通过 eventq 推送 DQBUF 事件给 Guest */
  virtio_media_send_dqbuf_event(be, s->session_id, &buf);
}
```
